<?php
$clients=db()->query('SELECT id,name FROM clients WHERE active=1 ORDER BY name')->fetchAll();
$rows=db()->query('SELECT p.*,c.name client_name,pl.name plan_name,u.name recorded_name FROM payments p JOIN clients c ON c.id=p.client_id LEFT JOIN memberships m ON m.id=p.membership_id LEFT JOIN plans pl ON pl.id=m.plan_id LEFT JOIN users u ON u.id=p.recorded_by ORDER BY p.payment_date DESC,p.id DESC LIMIT 200')->fetchAll();
?>
<section class="card panel hidden" id="payment-form"><div class="panel-head"><h2>Registrar un pago</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="payment_create"><label>Cliente<select name="client_id" required><option value="">Seleccionar</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach; ?></select></label><label>Monto (Bs)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Fecha<input name="payment_date" type="date" value="<?=date('Y-m-d')?>" required></label><label>Método<select name="method"><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option><option value="tarjeta">Tarjeta</option><option value="qr">QR</option></select></label><label>Referencia<input name="reference" placeholder="Número de operación o concepto"></label><label>Membresía relacionada<select name="membership_id"><option value="">Pago general</option><?php foreach($rows as $r): if($r['membership_id']): ?><option value="<?=$r['membership_id']?>">#<?=$r['membership_id']?> · <?=h($r['client_name'])?></option><?php endif; endforeach; ?></select></label><div class="form-actions"><button class="btn primary">Guardar pago</button></div></form></section>
<section class="card panel"><div class="panel-head"><h2>Historial de pagos <small>(últimos <?=count($rows)?>)</small></h2><input class="search" data-search="#payment-table" placeholder="Buscar cliente o referencia…"></div><div class="table-wrap"><table id="payment-table"><thead><tr><th>FECHA</th><th>CLIENTE</th><th>CONCEPTO</th><th>MÉTODO</th><th>REGISTRADO POR</th><th>MONTO</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=date('d/m/Y',strtotime($r['payment_date']))?></td><td><?=h($r['client_name'])?></td><td><?=h($r['reference']?:($r['plan_name']??'Pago'))?></td><td><?=h(ucfirst($r['method']))?></td><td><?=h($r['recorded_name']??'—')?></td><td><b><?=money($r['amount'])?></b></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">Aún no se registraron pagos.</td></tr><?php endif; ?></tbody></table></div></section>
